properties.property:
[
  {
    "text": "Before you stands an ancient crystalline formation, pulsing with primordial mana. The diamonds here are remnants of Shandalar's earliest age, and can be exchanged for spells from the dawn of magic itself.",
    "options": [
      {
        "name": "Trade 10,000 Gold for Beta Pack",
        "condition": [
          { "hasGold": 10000 }
        ],
        "text": "The crystals shimmer and absorb your gold. In exchange, a sealed pack from the dawn of magic materializes before you!",
        "action": [
          {
            "addGold": -10000,
            "grantRewards": [
              { "type": "cardPackShop", "count": 1, "editions": ["LEB"] }
            ]
          }
        ]
      },
      {
        "name": "Trade 10,000 Gold for Beta Pack",
        "condition": [
          { "hasGold": 10000, "not": true }
        ],
        "text": "You don't have enough gold. The ancient diamonds require 10,000 gold to activate."
      },
      {
        "name": "Trade 400 Shards for Beta Pack",
        "condition": [
          { "hasShards": 400 }
        ],
        "text": "The crystals shimmer and absorb your mana shards. In exchange, a sealed pack from the dawn of magic materializes before you!",
        "action": [
          {
            "addShards": -400,
            "grantRewards": [
              { "type": "cardPackShop", "count": 1, "editions": ["LEB"] }
            ]
          }
        ]
      },
      {
        "name": "Trade 400 Shards for Beta Pack",
        "condition": [
          { "hasShards": 400, "not": true }
        ],
        "text": "You don't have enough mana shards. The ancient diamonds require 400 shards to activate."
      },
      {
        "name": "Leave",
        "text": ""
      }
    ]
  }
]
